package org.apache.commons.math.geometry;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Vector3D_crossProduct_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testCrossProduct_StandardBasisVectors() {
        Vector3D i = new Vector3D(1.0, 0.0, 0.0);
        Vector3D j = new Vector3D(0.0, 1.0, 0.0);
        Vector3D k = new Vector3D(0.0, 0.0, 1.0);

        // i x j = k
        Vector3D result1 = Vector3D.crossProduct(i, j);
        assertVectorEquals(k, result1);

        // j x i = -k
        Vector3D result2 = Vector3D.crossProduct(j, i);
        assertVectorEquals(k.negate(), result2);

        // j x k = i
        Vector3D result3 = Vector3D.crossProduct(j, k);
        assertVectorEquals(i, result3);

        // k x j = -i
        Vector3D result4 = Vector3D.crossProduct(k, j);
        assertVectorEquals(i.negate(), result4);
    }













    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        Assert.assertEquals("X coordinate mismatch", expected.getX(), actual.getX(), EPSILON);
        Assert.assertEquals("Y coordinate mismatch", expected.getY(), actual.getY(), EPSILON);
        Assert.assertEquals("Z coordinate mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}

